import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { IsNull, type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { SchemeEntity } from "#/modules/reference/schema/entities/scheme.entity.ts";
import * as Scheme from "#/modules/reference/schema/types/scheme/index.ts";

/**
 * Repository of Scheme: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class SchemeRepository
  extends EntityRepository<
    SchemeEntity,
    Scheme.Types.SchemeSortableField,
    Scheme.Types.SchemeEditableField,
    Scheme.Types.SchemeSelectableField,
    Scheme.Types.ISchemeCreatable
  >
  implements IUpdatableRepository<SchemeEntity, Scheme.Types.ISchemeUpdatable>
{
  constructor(
    @InjectRepository(SchemeEntity)
    repository: Repository<SchemeEntity>,
  ) {
    super(repository, Scheme.Config.SCHEME_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(
    id: string,
    data: Scheme.Types.ISchemeUpdatable,
  ): Promise<SchemeEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the scheme with this code (unique). */
  async findByCode(code: NonNullable<SchemeEntity["code"]>): Promise<SchemeEntity | null> {
    return await this.findOne({ code, deletedAt: IsNull() });
  }
}
